<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='create'){try{$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));if($title===''||mb_strlen($title)>120)throw new RuntimeException('Judul wajib diisi dan maksimal 120 karakter.');if(mb_strlen($description)>500)throw new RuntimeException('Deskripsi maksimal 500 karakter.');$file=store_image($_FILES['template_image']??[],__DIR__.'/uploads');$pdo->prepare("INSERT INTO twibbons(slug,owner_id,visibility,title,description,template_image) VALUES(?,?,'public',?,?,?)")->execute([random_slug(),current_user()['id'],$title,$description,$file]);flash('success','Template publik berhasil diterbitkan.');}catch(Throwable $e){flash('error',$e->getMessage());}}
 elseif($action==='delete'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$stmt=$pdo->prepare('SELECT template_image FROM twibbons WHERE id=?');$stmt->execute([$id]);if($item=$stmt->fetch()){$pdo->prepare('DELETE FROM twibbons WHERE id=?')->execute([$id]);$path=__DIR__.'/uploads/'.basename($item['template_image']);if(is_file($path)&&basename($path)!=='sample_template.png')@unlink($path);flash('success','Template berhasil dihapus.');}}
 header('Location: admin');exit;}
$flash=pull_flash();$items=$pdo->query("SELECT t.*,u.name author_name,u.email author_email FROM twibbons t LEFT JOIN users u ON u.id=t.owner_id WHERE t.visibility='public' ORDER BY t.created_at DESC")->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Template Publik — Bingkaiin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">B</span>Bingkaiin</a></div></header><main class="container"><div class="page-head dashboard-head"><div><span class="eyebrow">Administrator</span><h1 class="page-title" style="margin-top:12px">Kelola template publik</h1><p class="subtitle">Tambahkan desain, lihat pembuatnya, dan atur koleksi yang tampil di beranda.</p></div><span class="btn btn-secondary"><?=count($items)?> template publik</span></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><div class="template-admin-layout"><section class="panel template-create"><div class="form-heading"><span class="form-icon">＋</span><div><h2>Template baru</h2><p>Diterbitkan atas nama <?=e(current_user()['name'])?></p></div></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="field"><label for="title">Judul template</label><input id="title" name="title" required maxlength="120" placeholder="Contoh: Hari Kemerdekaan"></div><div class="field"><label for="description">Deskripsi singkat</label><textarea id="description" name="description" rows="3" maxlength="500" placeholder="Jelaskan kampanye ini"></textarea></div><div class="field"><label for="template_image">Bingkai template</label><input id="template_image" name="template_image" type="file" accept="image/png,image/jpeg,image/webp" required></div><button class="btn btn-primary" style="width:100%">Publikasikan template</button></form></section><section><div class="admin-template-grid"><?php foreach($items as $item):?><article class="admin-template-card"><img src="uploads/<?=e(basename($item['template_image']))?>" alt=""><div class="admin-template-content"><div class="template-meta"><span class="visibility visibility-public">Publik</span><span><?=date('d M Y',strtotime($item['created_at']))?></span></div><h2><?=e($item['title'])?></h2><p><?=e($item['description']?:'Tanpa deskripsi')?></p><div class="author-row"><span class="mini-avatar"><?=e(strtoupper(mb_substr($item['author_name']?:'A',0,1)))?></span><div><strong><?=e($item['author_name']?:'Administrator (data lama)')?></strong><small><?=e($item['author_email']?:'Pembuat tidak tercatat')?></small></div></div><div class="template-actions"><a class="btn btn-secondary btn-sm" href="admin/template/<?=(int)$item['id']?>/edit">Edit</a><a class="btn btn-secondary btn-sm" href="t/<?=e($item['slug'])?>">Buka</a><form method="post" onsubmit="return confirm('Hapus template publik ini?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form></div></div></article><?php endforeach?></div><?php if(!$items):?><div class="empty">Belum ada template publik.</div><?php endif?></section></div></main><footer class="footer">Bingkaiin · Produk digital dari Apins Digital</footer></body></html>
